#!/usr/bin/env python3
"""Generate EV Charging Network Performance & Grid Optimization Report."""

import pandas as pd
import numpy as np
import json
import html

# ── Load Data ────────────────────────────────────────────────────────────────
df = pd.read_csv("/app/benchmark/data.csv")
total_sessions = len(df)

# ── KPI Computation ──────────────────────────────────────────────────────────
avg_waiting_time = df["waiting_time"].mean()
avg_energy_consumed = df["energy_consumed_kWh"].mean()
mean_station_load = df["station_load"].mean()
mean_renewable_ratio = df["renewable_energy_ratio"].mean()
mean_optimization_reward = df["optimization_reward"].mean()

# ── Section 1: Station Utilization & Demand Analysis ─────────────────────────
demand_by_location = df.groupby("location_type").agg(
    sessions=("energy_consumed_kWh", "count"),
    avg_demand=("charging_demand", "mean"),
    avg_energy=("energy_consumed_kWh", "mean"),
    avg_station_load=("station_load", "mean"),
).reset_index()

demand_by_station = df.groupby("station_id").agg(
    location_type=("location_type", "first"),
    sessions=("energy_consumed_kWh", "count"),
    avg_demand=("charging_demand", "mean"),
    avg_energy=("energy_consumed_kWh", "mean"),
    avg_station_load=("station_load", "mean"),
    avg_queue=("queue_length", "mean"),
).reset_index().sort_values("avg_demand", ascending=False)

top10_stations = demand_by_station.head(10)

demand_by_timeslot_location = df.groupby(["time_slot", "location_type"]).agg(
    avg_demand=("charging_demand", "mean"),
    sessions=("energy_consumed_kWh", "count"),
    avg_queue=("queue_length", "mean"),
).reset_index()

timeslot_order = ["Off-Peak", "Mid-Peak", "Peak"]
demand_by_timeslot_location["time_slot"] = pd.Categorical(
    demand_by_timeslot_location["time_slot"], categories=timeslot_order, ordered=True
)
demand_by_timeslot_location = demand_by_timeslot_location.sort_values("time_slot")

# ── Section 2: Queue Length & Waiting Time Analysis ──────────────────────────
wait_by_timeslot_location = df.groupby(["time_slot", "location_type"]).agg(
    avg_wait=("waiting_time", "mean"),
    avg_queue=("queue_length", "mean"),
    median_wait=("waiting_time", "median"),
    p90_wait=("waiting_time", lambda x: x.quantile(0.9)),
    sessions=("waiting_time", "count"),
).reset_index()
wait_by_timeslot_location["time_slot"] = pd.Categorical(
    wait_by_timeslot_location["time_slot"], categories=timeslot_order, ordered=True
)
wait_by_timeslot_location = wait_by_timeslot_location.sort_values(["time_slot", "location_type"])

wait_by_traffic = df.groupby("traffic_density").agg(
    avg_wait=("waiting_time", "mean"),
    avg_queue=("queue_length", "mean"),
    sessions=("waiting_time", "count"),
).reset_index()

wait_by_vehicle = df.groupby("vehicle_type").agg(
    avg_wait=("waiting_time", "mean"),
    avg_queue=("queue_length", "mean"),
    sessions=("waiting_time", "count"),
).reset_index().sort_values("avg_wait", ascending=False)

wait_by_station = df.groupby("station_id").agg(
    location_type=("location_type", "first"),
    avg_wait=("waiting_time", "mean"),
    avg_queue=("queue_length", "mean"),
    sessions=("waiting_time", "count"),
).reset_index().sort_values("avg_wait", ascending=False)

top10_wait_stations = wait_by_station.head(10)

# ── Section 3: Energy Consumption & Grid Load Patterns ───────────────────────
energy_by_timeslot = df.groupby("time_slot").agg(
    avg_energy=("energy_consumed_kWh", "mean"),
    avg_load=("station_load", "mean"),
    avg_power=("charging_power_kW", "mean"),
    sessions=("energy_consumed_kWh", "count"),
).reset_index()
energy_by_timeslot["time_slot"] = pd.Categorical(
    energy_by_timeslot["time_slot"], categories=timeslot_order, ordered=True
)
energy_by_timeslot = energy_by_timeslot.sort_values("time_slot")

energy_by_day = df.groupby("day_of_week").agg(
    avg_energy=("energy_consumed_kWh", "mean"),
    avg_load=("station_load", "mean"),
    sessions=("energy_consumed_kWh", "count"),
).reset_index()
day_order = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
energy_by_day["day_of_week"] = pd.Categorical(
    energy_by_day["day_of_week"], categories=day_order, ordered=True
)
energy_by_day = energy_by_day.sort_values("day_of_week")

load_by_timeslot_location = df.groupby(["time_slot", "location_type"]).agg(
    avg_load=("station_load", "mean"),
    avg_energy=("energy_consumed_kWh", "mean"),
    sessions=("energy_consumed_kWh", "count"),
).reset_index()
load_by_timeslot_location["time_slot"] = pd.Categorical(
    load_by_timeslot_location["time_slot"], categories=timeslot_order, ordered=True
)
load_by_timeslot_location = load_by_timeslot_location.sort_values(["time_slot", "location_type"])

power_levels = df["charging_power_kW"].unique()
