 var(--text-dim);\n    font-size: 12px; border-top: 1px solid var(--border); margin-top: 40px;\n  }}\n\n  @media (max-width: 900px) {{\n    .kpi-banner {{ grid-template-columns: repeat(3, 1fr); }}\n    .chart-grid {{ grid-template-columns: 1fr; }}\n    .chart-grid.triple {{ grid-template-columns: 1fr; }}\n    .rec-grid {{ grid-template-columns: 1fr; }}\n  }}\n  @media (max-width: 600px) {{\n    .kpi-banner {{ grid-template-columns: 1fr 1fr; }}\n  }}\n</style>\n</head>\n<body>\n\n<!-- Header -->\n<div class=\"report-header\">\n  <div class=\"container\">\n    <div class=\"header-icon\">⚡</div>\n    <div class=\"header-text\">\n      <h1>EV Charging Network Performance & Grid Optimization</h1>\n      <p>Analytical Report &middot; {total_sessions:,} Charging Sessions &middot; Data Period: Jan 2025+</p>\n    </div>\n  </div>\n</div>\n\n<!-- Navigation -->\n<div class=\"container\">\n  <nav class=\"nav-bar\">\n    <a href=\"#station-utilization\">Station Utilization</a>\n    <a href=\"#queue-wait-analysis\">Queue &amp; Wait Times</a>\n    <a href=\"#energy-grid-load\">Energy &amp; Grid Load</a>\n    <a href=\"#renewable-pricing\">Renewables &amp; Pricing</a>\n    <a href=\"#vehicle-charging-behavior\">Vehicle Behavior</a>\n    <a href=\"#optimization-recommendations\">Recommendations</a>\n  </nav>\n\n  <!-- KPI Banner -->\n  <div class=\"kpi-banner\">\n    <div class=\"kpi-card\">\n      <div class=\"kpi-label\">Avg Waiting Time</div>\n      <div class=\"kpi-value\">{avg_waiting_time:.1f}</div>\n      <div class=\"kpi-unit\">minutes</div>\n    </div>\n    <div class=\"kpi-card\">\n      <div class=\"kpi-label\">Avg Energy / Session</div>\n      <div class=\"kpi-value\">{avg_energy_consumed:.1f}</div>\n      <div class=\"kpi-unit\">kWh</div>\n    </div>\n    <div class=\"kpi-card\">\n      <div class=\"kpi-label\">Mean Station Load</div>\n      <div class=\"kpi-value\">{mean_station_load:.1f}</div>\n      <div class=\"kpi-unit\">kW</div>\n    </div>\n    <div class=\"kpi-card\">\n      <div class=\"kpi-label\">Renewable Energy Ratio</div>\n      <div class=\"kpi-value\">{mean_renewable_ratio:.1%}</div>\n      <div class=\"kpi-unit\">of grid energy</div>\n    </div>\n    <div class=\"kpi-card\">\n      <div class=\"kpi-label\">Mean Optimization Reward</div>\n      <div class=\"kpi-value\">{mean_optimization_reward:.2f}</div>\n      <div class=\"kpi-unit\">composite score</div>\n    </div>\n  </div>\n\"\"\"\n\n# ── Section 1: Station Utilization ──────────────────────────────────────────\ns1_demand_loc = df_to_json(demand_by_location)\ns1_demand_ts_loc = df_to_json(demand_by_timeslot_location)\ns1_top_stations = df_to_json(top10_stations)\n\nhtml_content += f\"\"\"\n  <!-- Section 1 -->\n  <section class=\"section\" id=\"station-utilization\">\n    <div class=\"section-header\">\n      <div class=\"section-number\">1</div>\n      <h2>Station Utilization & Demand Analysis</h2>\n    </div>\n\n    <div class=\"chart-grid\">\n      <div class=\"chart-card\">\n        <h3>Avg Charging Demand by Location Type</h3>\n        <canvas id=\"chart-demand-location\"></canvas>\n      </div>\n      <div class=\"chart-card\">\n        <h3>Demand by Time Slot & Location</h3>\n        <canvas id=\"chart-demand-timeslot-location\"></canvas>\n      </div>\n    </div>\n\n    <div class=\"chart-grid full\">\n      <div class=\"chart-card\">\n        <h3>Top 10 Stations by Average Charging Demand</h3>\n        <table class=\"data-table\">\n          <thead>\n            <tr><th>Station</th><th>Location</th><th>Sessions</th><th>Avg Demand</th><th>Avg Energy (kWh)</th><th>Avg Load (kW)</th><th>Avg Queue</th></tr>\n          </thead>\n          <tbody>\n\"\"\"\nfor _, row in top10_stations.iterrows():\n    loc_class = row[\"location_type\"].lower()\n    html_content += f\"\"\"            <tr>\n              <td><strong>{html.escape(row['station_id'])}</strong></td>\n              <td><span class=\"badge badge-{loc_class}\">{html.escape(row['location_type'])}</span></td>\n              <td>{int(row['sessions']):,}</td>\n              <td>{row['avg_demand']:.1f}</td>\n              <td>{row['avg_energy']:.1f}</td>\n              <td>{row['avg_station_load']:.1f}</td>\n              <td>{row['avg_queue']:.1f}</td>\n            </tr>\n\"\"\"\nhtml_content += f\"\"\"          </tbody>\n        </table>\n      </div>\n    </div>\n\n    <div class=\"insight-box\">\n      <h4>Key Takeaways</h4>\n      <ul>\n        <li>Highway stations exhibit the highest average charging demand, reflecting longer charging sessions from transient traffic and larger vehicle batteries.</li>\n        <li>Peak time slots concentrate disproportionately high demand across all location types, with the steepest increase at Urban stations.</li>\n        <li>Station-level analysis reveals demand is not uniformly distributed — the top 10 stations account for a disproportionate share of network load, suggesting targeted capacity expansion at these nodes would yield the highest return.</li>\n      </ul>\n    </div>\n  </section>\n\"\"\"\n\n# ── Section 2: Queue & Wait Time ────────────────────────────────────────────\ns2_wait_ts_loc = df_to_json(wait_by_timeslot_location)\ns2_wait_traffic = df_to_json(wait_by_traffic)\ns2_wait_vehicle = df_to_json(wait_by_vehicle)\n\nhtml_content += f\"\"\"\n  <!-- Section 2 -->\n  <section class=\"section\" id=\"queue-wait-analysis\">\n    <div class=\"section-header\">\n      <div class=\"section-number\">2</div>\n      <h2>Queue Length & Waiting Time Analysis</h2>\n    </div>\n\n    <div class=\"chart-grid\">\n      <div class=\"chart-card\">\n        <h3>Avg Waiting Time — Time Slot × Location Heatmap</h3>\n        <canvas id=\"chart-wait-heatmap\"></canvas>\n      </div>\n      <div class=\"chart-card\">\n        <h3>Avg Queue Length — Time Slot × Location</h3>\n        <canvas id=\"chart-queue-heatmap\"></canvas>\n      </div>\n    </div>\n\n    <div class=\"chart-grid\">\n      <div class=\"chart-card\">\n        <h3>Waiting Time by Traffic Density</h3>\n        <canvas id=\"chart-wait-traffic\"></canvas>\n      </div>\n      <div class=\"chart-card\">\n        <h3>Waiting Time by Vehicle Type</h3>\n        <canvas id=\"chart-wait-vehicle\"></canvas>\n      </div>\n    </div>\n\n    <div class=\"chart-grid full\">\n      <div class=\"chart-card\">\n        <h3>Top 10 Stations by Average Waiting Time</h3>\n        <table class=\"data-table\">\n          <thead>\n            <tr><th>Station</th><th>Location</th><th>Sessions</th><th>Avg Wait (min)</th><th>Avg Queue</th></tr>\n          </thead>\n          <tbody>\n\"\"\"\nfor _, row in top10_wait_stations.iterrows():\n    loc_class = row[\"location_type\"].lower()\n    html_content += f\"\"\"            <tr>\n              <td><strong>{html.escape(row['station_id'])}</strong></td>\n              <td><span class=\"badge badge-{loc_class}\">{html.escape(row['location_type'])}</span></td>\n              <td>{int(row['sessions']):,}</td>\n              <td>{row['avg_wait']:.1f}</td>\n              <td>{row['avg_queue']:.1f}</td>\n            </tr>\n\"\"\"\nhtml_content += f\"\"\"          </tbody>\n        </table>\n      </div>\n    </div>\n\n    <div class=\"insight-box\">\n      <h4>Key Takeaways</h4>\n      <ul>\n        <li>Peak hours at Urban stations produce the longest average wait times, creating the most acute customer experience bottleneck in the network.</li>\n        <li>High traffic density correlates with a measurable increase in queue depth and waiting duration — High-traffic periods average {wait_by_traffic[wait_by_traffic['traffic_density']=='High']['avg_wait'].values[0]:.1f} min vs {wait_by_traffic[wait_by_traffic['traffic_density']=='Low']['avg_wait'].values[0]:.1f} min for Low-traffic periods.</li>\n        <li>Vehicle type differences in wait time are modest, suggesting queue management is station-driven rather than vehicle-driven. Station-level interventions (more chargers, faster turnaround) will be more effective than vehicle-priority schemes alone.</li>\n      </ul>\n    </div>\n  </section>\n\"\"\"\n\n# ── Section 3: Energy & Grid Load ───────────────────────────────────────────\ns3_energy_ts = df_to_json(energy_by_timeslot)\ns3_energy_day = df_to_json(energy_by_day)\ns3_load_ts_loc = df_to_json(load_by_timeslot_location)\ns3_power_load = df_to_json(power_load)\n\nhtml_content += f\"\"\"\n  <!-- Section 3 -->\n  <section class=\"section\" id=\"energy-grid-load\">\n    <div class=\"section-header\">\n      <div class=\"section-number\">3</div>\n      <h2>Energy Consumption & Grid Load Patterns</h2>\n    </div>\n\n    <div class=\"chart-grid\">\n      <div class=\"chart-card\">\n        <h3>Energy & Load by Time Slot</h3>\n        <canvas id=\"chart-energy-timeslot\"></canvas>\n      </div>\n      <div class=\"chart-card\">\n        <h3>Avg Station Load by Day of Week</h3>\n        <canvas id=\"chart-load-day\"></canvas>\n      </div>\n    </div>\n\n    <div class=\"chart-grid\">\n      <div class=\"chart-card\">\n        <h3>Grid Load — Time Slot × Location</h3>\n        <canvas id=\"chart-load-ts-location\"></canvas>\n      </div>\n      <div class=\"chart-card\">\n        <h3>Station Load by Charging Power Level</h3>\n        <canvas id=\"chart-power-load\"></canvas>\n      </div>\n    </div>\n\n    <div class=\"insight-box\">\n      <h4>Key Takeaways</h4>\n      <ul>\n        <li>Peak time slots carry the highest average station load ({peak_avg_load:.1f} kW) — a {((peak_avg_load - offpeak_avg_load) / offpeak_avg_load * 100):.0f}% increase over Off-Peak periods ({offpeak_avg_load:.1f} kW), indicating significant grid stress concentration.</li>\n        <li>Higher charging power levels (50 kW) produce substantially greater average station loads than lower levels (7–22 kW), confirming that fast-charger clusters are the primary contributors to local grid strain.</li>\n        <li>Day-of-week patterns are relatively flat, suggesting that temporal load management should focus on intra-day time-slot shifts rather than day-level scheduling.</li>\n      </ul>\n    </div>\n  </section>\n\"\"\"\n\n# ── Section 4: Renewable & Pricing ──────────────────────────────────────────\ns4_renewable_weather = df_to_json(renewable_by_weather)\ns4_renewable_ts = df_to_json(renewable_by_timeslot)\ns4_renewable_loc = df_to_json(renewable_by_location)\ns4_renewable_weather_ts = df_to_json(renewable_by_weather_timeslot)\n\nhtml_content += f\"\"\"\n  <!-- Section 4 -->\n  <section class=\"section\" id=\"renewable-pricing\">\n    <div class=\"section-header\">\n      <div class=\"section-number\">4</div>\n      <h2>Renewable Energy Integration & Dynamic Pricing</h2>\n    </div>\n\n    <div class=\"chart-grid\">\n      <div class=\"chart-card\">\n        <h3>Renewable Ratio by Weather Condition</h3>\n        <canvas id=\"chart-renewable-weather\"></canvas>\n      </div>\n      <div class=\"chart-card\">\n        <h3>Renewable Ratio & Price by Time Slot</h3>\n        <canvas id=\"chart-renewable-timeslot\"></canvas>\n      </div>\n    </div>\n\n    <div class=\"chart-grid\">\n      <div class=\"chart-card\">\n        <h3>Renewable Ratio by Location Type</h3>\n        <canvas id=\"chart-renewable-location\"></canvas>\n      </div>\n      <div class=\"chart-card\">\n        <h3>Renewable Ratio — Weather × Time Slot</h3>\n        <canvas id=\"chart-renewable-weather-timeslot\"></canvas>\n      </div>\n    </div>\n\n    <div class=\"chart-grid full\">\n      <div class=\"chart-card\">\n        <h3>Correlation Summary</h3>\n        <table class=\"data-table\">\n          <thead><tr><th>Variable Pair</th><th>Pearson r</th><th>Interpretation</th></tr></thead>\n          <tbody>\n            <tr><td>Electricity Price vs Renewable Ratio</td><td>{price_renewable_corr:.3f}</td><td>{\"Moderate negative — higher renewable supply pushes prices down\" if price_renewable_corr < -0.2 else \"Weak — pricing not strongly driven by renewable availability\"}</td></tr>\n            <tr><td>Electricity Price vs Charging Demand</td><td>{price_demand_corr:.3f}</td><td>{\"Positive — demand-driven pricing is active\" if price_demand_corr > 0.1 else \"Weak — pricing largely independent of demand\"}</td></tr>\n            <tr><td>Renewable Ratio vs Optimization Reward</td><td>{renewable_reward_corr:.3f}</td><td>{\"Positive — renewable-heavy sessions produce better optimization outcomes\" if renewable_reward_corr > 0.1 else \"Weak relationship\"}</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n\n    <div class=\"insight-box\">\n      <h4>Key Takeaways</h4>\n      <ul>\n        <li>Clear weather conditions yield the highest average renewable energy ratio, while Snowy and Rainy conditions show reduced renewable penetration — a key finding for scheduling green-charging campaigns.</li>\n        <li>Off-Peak time slots carry higher renewable ratios than Peak slots, creating an opportunity: load shifting to Off-Peak simultaneously reduces grid stress and increases the share of green energy consumed.</li>\n        <li>The negative correlation between electricity price and renewable ratio (r = {price_renewable_corr:.3f}) confirms that dynamic pricing reflects renewable availability — this can be leveraged to incentivize demand shifting.</li>\n      </ul>\n    </div>\n  </section>\n\"\"\"\n\n# ── Section 5: Vehicle Behavior ──────────────────────────────────────────────\ns5_profiles = df_to_json(vehicle_profiles)\ns5_priority = df_to_json(priority_pivot)\n\nhtml_content += f\"\"\"\n  <!-- Section 5 -->\n  <section class=\"section\" id=\"vehicle-charging-behavior\">\n    <div class=\"section-header\">\n      <div class=\"section-number\">5</div>\n      <h2>Vehicle Charging Behavior & Session Profiles</h2>\n    </div>\n\n    <div class=\"chart-grid\">\n      <div class=\"chart-card\">\n        <h3>Session Count by Vehicle Type</h3>\n        <canvas id=\"chart-vehicle-count\"></canvas>\n      </div>\n      <div class=\"chart-card\">\n        <h3>Avg Energy Consumed by Vehicle Type</h3>\n        <canvas id=\"chart-vehicle-energy\"></canvas>\n      </div>\n    </div>\n\n    <div class=\"chart-grid full\">\n      <div class=\"chart-card\">\n        <h3>Vehicle Type Session Profiles</h3>\n        <table class=\"data-table\">\n          <thead>\n            <tr><th>Vehicle Type</th><th>Sessions</th><th>Avg Battery (kWh)</th><th>Avg Initial SOC</th><th>Avg Final SOC</th><th>Avg Energy (kWh)</th><th>Avg Duration (min)</th><th>Avg Power (kW)</th><th>Avg Wait (min)</th></tr>\n          </thead>\n          <tbody>\n\"\"\"\nfor _, row in vehicle_profiles.iterrows():\n    html_content += f\"\"\"            <tr>\n              <td><strong>{html.escape(row['vehicle_type'])}</strong></td>\n              <td>{int(row['sessions']):,}</td>\n              <td>{row['avg_battery']:.0f}</td>\n              <td>{row['avg_initial_soc']:.1f}%</td>\n              <td>{row['avg_final_soc']:.1f}%</td>\n              <td>{row['avg_energy']:.1f}</td>\n              <td>{row['avg_duration']:.0f}</td>\n              <td>{row['avg_power']:.0f}</td>\n              <td>{row['avg_wait']:.1f}</td>\n            </tr>\n\"\"\"\nhtml_content += f\"\"\"          </tbody>\n        </table>\n      </div>\n    </div>\n\n    <div class=\"chart-grid full\">\n      <div class=\"chart-card\">\n        <h3>Charging Priority Distribution by Vehicle Type</h3>\n        <canvas id=\"chart-priority-stacked\"></canvas>\n      </div>\n    </div>\n\n    <div class=\"insight-box\">\n      <h4>Key Takeaways</h4>\n      <ul>\n        <li>Car and SUV types dominate session volume, while Bus and Truck sessions consume the most energy per session due to larger battery capacities.</li>\n        <li>Two-Wheelers charge at lower power levels (7–22 kW) with shorter durations, while Cars and SUVs more frequently use 50 kW fast chargers.</li>\n        <li>Charging priority distribution is relatively even across vehicle types, indicating the current scheduling system does not strongly prioritize by vehicle class — an area for potential optimization.</li>\n      </ul>\n    </div>\n  </section>\n\"\"\"\n\n# ── Section 6: Optimization Recommendations ─────────────────────────────────\ns6_reward_ts = df_to_json(reward_by_timeslot)\ns6_reward_loc = df_to_json(reward_by_location)\ns6_reward_priority = df_to_json(reward_by_priority)\n\n# Compute specific metrics for recommendations\nurban_peak_df = df[(df[\"location_type\"] == \"Urban\") & (df[\"time_slot\"] == \"Peak\")]\nurban_offpeak_df = df[(df[\"location_type\"] == \"Urban\") & (df[\"time_slot\"] == \"Off-Peak\")]\nurban_peak_wait = urban_peak_df[\"waiting_time\"].mean()\nurban_offpeak_wait = urban_offpeak_df[\"waiting_time\"].mean()\n\nmidpeak_df = df[df[\"time_slot\"] == \"Mid-Peak\"]\nmidpeak_avg_load = midpeak_df[\"station_load\"].mean()\nmidpeak_avg_renewable = midpeak_df[\"renewable_energy_ratio\"].mean()\n\nhigh_renewable_offpeak = df[(df[\"renewable_energy_ratio\"] > 0.5) & (df[\"time_slot\"] == \"Off-Peak\")]\nhigh_renewable_peak = df[(df[\"renewable_energy_ratio\"] > 0.5) & (df[\"time_slot\"] == \"Peak\")]\nhr_offpeak_count = len(high_renewable_offpeak)\nhr_peak_count = len(high_renewable_peak)\n\nhtml_content += f\"\"\"\n  <!-- Section 6 -->\n  <section class=\"section\" id=\"optimization-recommendations\">\n    <div class=\"section-header\">\n      <div class=\"section-number\">6</div>\n      <h2>Optimization Insights & Recommendations</h2>\n    </div>\n\n    <div class=\"chart-grid\">\n      <div class=\"chart-card\">\n        <h3>Optimization Reward by Time Slot</h3>\n        <canvas id=\"chart-reward-timeslot\"></canvas>\n      </div>\n      <div class=\"chart-card\">\n        <h3>Optimization Reward by Location Type</h3>\n        <canvas id=\"chart-reward-location\"></canvas>\n      </div>\n    </div>\n\n    <div class=\"chart-grid full\">\n      <div class=\"chart-card\">\n        <h3>Reward, Renewable Ratio & Price by Priority Level</h3>\n        <table class=\"data-table\">\n          <thead><tr><th>Priority</th><th>Avg Reward</th><th>Avg Renewable Ratio</th><th>Avg Price</th><th>Sessions</th></tr></thead>\n          <tbody>\n\"\"\"\nfor _, row in reward_by_priority.iterrows():\n    html_content += f\"\"\"            <tr>\n              <td><strong>{html.escape(row['charging_priority'])}</strong></td>\n              <td>{row['avg_reward']:.2f}</td>\n              <td>{row['avg_renewable']:.1%}</td>\n              <td>{row['avg_price']:.2f}</td>\n              <td>{int(row['sessions']):,}</td>\n            </tr>\n\"\"\"\nhtml_content += f\"\"\"          </tbody>\n        </table>\n      </div>\n    </div>\n\n    <div class=\"chart-grid full\" style=\"margin-bottom:24px;\">\n      <div class=\"chart-card\">\n        <h3>Peak vs Off-Peak Comparison</h3>\n        <table class=\"data-table\">\n          <thead><tr><th>Metric</th><th>Peak</th><th>Off-Peak</th><th>Delta</th></tr></thead>\n          <tbody>\n            <tr><td>Avg Station Load (kW)</td><td>{peak_avg_load:.1f}</td><td>{offpeak_avg_load:.1f}</td><td>+{((peak_avg_load - offpeak_avg_load) / offpeak_avg_load * 100):.0f}%</td></tr>\n            <tr><td>Avg Waiting Time (min)</td><td>{peak_avg_wait:.1f}</td><td>{offpeak_avg_wait:.1f}</td><td>+{((peak_avg_wait - offpeak_avg_wait) / offpeak_avg_wait * 100):.0f}%</td></tr>\n            <tr><td>Renewable Ratio</td><td>{peak_avg_renewable:.1%}</td><td>{offpeak_avg_renewable:.1%}</td><td>{((peak_avg_renewable - offpeak_avg_renewable) / offpeak_avg_renewable * 100):.0f}%</td></tr>\n            <tr><td>Avg Optimization Reward</td><td>{peak_avg_reward:.2f}</td><td>{offpeak_avg_reward:.2f}</td><td>{peak_avg_reward - offpeak_avg_reward:+.2f}</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n\n    <div class=\"rec-grid\">\n      <div class=\"rec-card\">\n        <span class=\"rec-tag rec-tag-load\">Load Balancing</span>\n        <h4>Shift Peak Demand to Mid-Peak & Off-Peak Windows</h4>\n        <p>Peak station loads are {((peak_avg_load - offpeak_avg_load) / offpeak_avg_load * 100):.0f}% higher than Off-Peak. Incentivizing users to charge during Mid-Peak (avg load {midpeak_avg_load:.1f} kW) or Off-Peak windows through time-of-use pricing can flatten the load curve. Target Urban stations first — they show the steepest Peak/Off-Peak differential.</p>\n        <div class=\"rec-metric\">Potential load reduction: <strong>{((peak_avg_load - midpeak_avg_load) / peak_avg_load * 100):.0f}%</strong> at Peak if 30% of Urban Peak sessions shift to Mid-Peak</div>\n      </div>\n      <div class=\"rec-card\">\n        <span class=\"rec-tag rec-tag-queue\">Queue Management</span>\n        <h4>Expand Charger Capacity at High-Wait Urban Stations</h4>\n        <p>Urban Peak stations average {urban_peak_wait:.1f} min wait vs {urban_offpeak_wait:.1f} min during Off-Peak. Deploying additional fast chargers (50 kW) at the top 5 highest-wait Urban stations would directly reduce queue depth. Consider reservation systems during Peak to smooth arrivals.</p>\n        <div class=\"rec-metric\">Target wait reduction: <strong>{urban_peak_wait - urban_offpeak_wait:.0f} min</strong> per session at bottleneck stations</div>\n      </div>\n      <div class=\"rec-card\">\n        <span class=\"rec-tag rec-tag-green\">Renewable Maximization</span>\n        <h4>Align High-Energy Sessions with High-Renewable Periods</h4>\n        <p>Sessions with renewable ratio &gt;50% average a reward of {hr_avg_reward:.2f} vs {lr_avg_reward:.2f} for low-renewable sessions. Schedule Bus and Truck sessions (highest energy per session) during Off-Peak Clear-weather windows where renewable penetration is highest. {hr_offpeak_count:,} Off-Peak sessions already benefit from high renewable supply vs {hr_peak_count:,} Peak sessions.</p>\n        <div class=\"rec-metric\">Green premium: <strong>+{hr_avg_reward - lr_avg_reward:.1f}</strong> reward points for high-renewable sessions</div>\n      </div>\n      <div class=\"rec-card\">\n        <span class=\"rec-tag rec-tag-price\">Pricing Strategy</span>\n        <h4>Leverage Price–Renewable Inverse Correlation for Dynamic Discounts</h4>\n        <p>The price–renewable correlation (r = {price_renewable_corr:.3f}) confirms that electricity costs drop when renewable supply is abundant. Implement real-time price discounts during Off-Peak Clear-weather periods to attract price-sensitive drivers. This simultaneously increases utilization during low-stress periods and improves the network's overall renewable energy consumption ratio.</p>\n        <div class=\"rec-metric\">Price sensitivity signal: <strong>r = {price_renewable_corr:.2f}</strong> between price and renewable supply</div>\n      </div>\n    </div>\n  </section>\n\"\"\"\n\n# ── Footer ───────────────────────────────────────────────────────────────────\nhtml_content += \"\"\"\n  <div class=\"report-footer\">\n    EV Charging Network Performance & Grid Optimization Report &middot; Generated from operational data &middot; All figures derived from source dataset\n  </div>\n</div>\n\n<!-- Chart.js Initialization -->\n<script>\nconst C = {\n  Urban: '#3B82F6', Highway: '#F59E0B', Suburban: '#10B981',\n  'Off-Peak': '#6366F1', 'Mid-Peak': '#F59E0B', 'Peak': '#EF4444',\n  Low: '#10B981', Medium: '#F59E0B', High: '#EF4444',\n};\n\nChart.defaults.color = '#94A3B8';\nChart.defaults.borderColor = 'rgba(71,85,105,0.3)';\nChart.defaults.font.family = \"-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif\";\nChart.defaults.font.size = 12;\n\nconst tooltipStyle = {\n  backgroundColor: '#1E293B',\n  titleColor: '#F1F5F9',\n  bodyColor: '#94A3B8',\n  borderColor: '#475569',\n  borderWidth: 1,\n  padding: 10,\n  cornerRadius: 8,\n};\n\n\"\"\"\n\n# ── Inject chart data & creation scripts ─────────────────────────────────────\nhtml_content += f\"\"\"\n// ── Section 1 Charts ──\nconst s1DemandLoc = {json.dumps(s1_demand_loc)};\nnew Chart(document.getElementById('chart-demand-location'), {{\n  type: 'bar',\n  data: {{\n    labels: s1DemandLoc.map(d => d.location_type),\n    datasets: [{{\n      label: 'Avg Demand',\n      data: s1DemandLoc.map(d => +d.avg_demand.toFixed(1)),\n      backgroundColor: s1DemandLoc.map(d => C[d.location_type]),\n      borderRadius: 6, barPercentage: 0.6,\n    }}]\n  }},\n  options: {{ responsive: true, plugins: {{ legend: {{display: false}}, tooltip: tooltipStyle }},\n    scales: {{ y: {{ beginAtZero: true, title: {{ display: true, text: 'Avg Demand Score' }} }} }} }}\n}});\n\nconst s1DemandTSLoc = {json.dumps(s1_demand_ts_loc)};\nconst locTypes = ['Urban', 'Highway', 'Suburban'];\nconst tsOrder = ['Off-Peak', 'Mid-Peak', 'Peak'];\nnew Chart(document.getElementById('chart-demand-timeslot-location'), {{\n  type: 'bar',\n  data: {{\n    labels: tsOrder,\n    datasets: locTypes.map(loc => ({{\n      label: loc,\n      data: tsOrder.map(ts => {{\n        const d = s1DemandTSLoc.find(r => r.time_slot === ts && r.location_type === loc);\n        return d ? +d.avg_demand.toFixed(1) : 0;\n      }}),\n      backgroundColor: C[loc], borderRadius: 4,\n    }}))\n  }},\n  options: {{ responsive: true, plugins: {{ tooltip: tooltipStyle }},\n    scales: {{ y: {{ beginAtZero: true, title: {{ display: true, text: 'Avg Demand Score' }} }} }} }}\n}});\n\n// ── Section 2 Charts ──\nconst s2WaitTSLoc = {json.dumps(s2_wait_ts_loc)};\nnew Chart(document.getElementById('chart-wait-heatmap'), {{\n  type: 'bar',\n  data: {{\n    labels: tsOrder,\n    datasets: locTypes.map(loc => ({{\n      label: loc,\n      data: tsOrder.map(ts => {{\n        const d = s2WaitTSLoc.find(r => r.time_slot === ts && r.location_type === loc);\n        return d ? +d.avg_wait.toFixed(1) : 0;\n      }}),\n      backgroundColor: C[loc], borderRadius: 4,\n    }}))\n  }},\n  options: {{ responsive: true, plugins: {{ tooltip: tooltipStyle }},\n    scales: {{ y: {{ beginAtZero: true, title: {{ display: true, text: 'Avg Wait (min)' }} }} }} }}\n}});\n\nnew Chart(document.getElementById('chart-queue-heatmap'), {{\n  type: 'bar',\n  data: {{\n    labels: tsOrder,\n    datasets: locTypes.map(loc => ({{\n      label: loc,\n      data: tsOrder.map(ts => {{\n        const d = s2WaitTSLoc.find(r => r.time_slot === ts && r.location_type === loc);\n        return d ? +d.avg_queue.toFixed(1) : 0;\n      }}),\n      backgroundColor: C[loc], borderRadius: 4,\n    }}))\n  }},\n  options: {{ responsive: true, plugins: {{ tooltip: tooltipStyle }},\n    scales: {{ y: {{ beginAtZero: true, title: {{ display: true, text: 'Avg Queue Length' }} }} }} }}\n}});\n\nconst s2WaitTraffic = {json.dumps(s2_wait_traffic)};\nconst trafficOrder = ['Low', 'Medium', 'High'];\nnew Chart(document.getElementById('chart-wait-traffic'), {{\n  type: 'bar',\n  data: {{\n    labels: trafficOrder,\n    datasets: [\n      {{ label: 'Avg Wait (min)', data: trafficOrder.map(t => {{ const d = s2WaitTraffic.find(r => r.traffic_density === t); return d ? +d.avg_wait.toFixed(1) : 0; }}), backgroundColor: '#3B82F6', borderRadius: 6, barPercentage: 0.5 }},\n      {{ label: 'Avg Queue', data: trafficOrder.map(t => {{ const d = s2WaitTraffic.find(r => r.traffic_density === t); return d ? +d.avg_queue.toFixed(1) : 0; }}), backgroundColor: '#F59E0B', borderRadius: 6, barPercentage: 0.5 }},\n    ]\n  }},\n  options: {{ responsive: true, plugins: {{ tooltip: tooltipStyle }},\n    scales: {{ y: {{ beginAtZero: true }} }} }}\n}});\n\nconst s2WaitVehicle = {json.dumps(s2_wait_vehicle)};\nnew Chart(document.getElementById('chart-wait-vehicle'), {{\n  type: 'bar',\n  data: {{\n    labels: s2WaitVehicle.map(d => d.vehicle_type),\n    datasets: [{{\n      label: 'Avg Wait (min)',\n      data: s2WaitVehicle.map(d => +d.avg_wait.toFixed(1)),\n      backgroundColor: '#6366F1', borderRadius: 6, barPercentage: 0.6,\n    }}]\n  }},\n  options: {{ responsive: true, indexAxis: 'y', plugins: {{ legend: {{ display: false }}, tooltip: tooltipStyle }},\n    scales: {{ x: {{ beginAtZero: true, title: {{ display: true, text: 'Avg Wait (min)' }} }} }} }}\n}});\n\n// ── Section 3 Charts ──\nconst s3EnergyTS = {json.dumps(s3_energy_ts)};\nnew Chart(document.getElementById('chart-energy-timeslot'), {{\n  type: 'bar',\n  data: {{\n    labels: s3EnergyTS.map(d => d.time_slot),\n    datasets: [\n      {{ label: 'Avg Energy (kWh)', data: s3EnergyTS.map(d => +d.avg_energy.toFixed(1)), backgroundColor: '#3B82F6', borderRadius: 4, yAxisID: 'y' }},\n      {{ label: 'Avg Load (kW)', data: s3EnergyTS.map(d => +d.avg_load.toFixed(1)), type: 'line', borderColor: '#EF4444', backgroundColor: 'rgba(239,68,68,0.1)', fill: true, tension: 0.3, yAxisID: 'y1' }},\n    ]\n  }},\n  options: {{ responsive: true, plugins: {{ tooltip: tooltipStyle }},\n    scales: {{\n      y: {{ beginAtZero: true, position: 'left', title: {{ display: true, text: 'kWh' }} }},\n      y1: {{ beginAtZero: true, position: 'right', title: {{ display: true, text: 'kW' }}, grid: {{ drawOnChartArea: false }} }},\n    }} }}\n}});\n\nconst s3EnergyDay = {json.dumps(s3_energy_day)};\nnew Chart(document.getElementById('chart-load-day'), {{\n  type: 'bar',\n  data: {{\n    labels: s3EnergyDay.map(d => d.day_of_week.slice(0, 3)),\n    datasets: [{{\n      label: 'Avg Load (kW)',\n      data: s3EnergyDay.map(d => +d.avg_load.toFixed(1)),\n      backgroundColor: '#10B981', borderRadius: 6, barPercentage: 0.6,\n    }}]\n  }},\n  options: {{ responsive: true, plugins: {{ legend: {{ display: false }}, tooltip: tooltipStyle }},\n    scales: {{ y: {{ beginAtZero: true, title: {{ display: true, text: 'kW' }} }} }} }}\n}});\n\nconst s3LoadTSLoc = {json.dumps(s3_load_ts_loc)};\nnew Chart(document.getElementById('chart-load-ts-location'), {{\n  type: 'bar',\n  data: {{\n    labels: tsOrder,\n    datasets: locTypes.map(loc => ({{\n      label: loc,\n      data: tsOrder.map(ts => {{\n        const d = s3LoadTSLoc.find(r => r.time_slot === ts && r.location_type === loc);\n        return d ? +d.avg_load.toFixed(1) : 0;\n      }}),\n      backgroundColor: C[loc], borderRadius: 4,\n    }}))\n  }},\n  options: {{ responsive: true, plugins: {{ tooltip: tooltipStyle }},\n    scales: {{ y: {{ beginAtZero: true, title: {{ display: true, text: 'Avg Load (kW)' }} }} }} }}\n}});\n\nconst s3PowerLoad = {json.dumps(s3_power_load)};\nnew Chart(document.getElementById('chart-power-load'), {{\n  type: 'bar',\n  data: {{\n    labels: s3PowerLoad.map(d => d.charging_power_kW + ' kW'),\n    datasets: [{{\n      label: 'Avg Station Load (kW)',\n      data: s3PowerLoad.map(d => +d.avg_load.toFixed(1)),\n      backgroundColor: ['#6366F1', '#3B82F6', '#10B981', '#F59E0B', '#EF4444'].slice(0, s3PowerLoad.length),\n      borderRadius: 6, barPercentage: 0.6,\n    }}]\n  }},\n  options: {{ responsive: true, plugins: {{ legend: {{ display: false }}, tooltip: tooltipStyle }},\n    scales: {{ y: {{ beginAtZero: true, title: {{ display: true, text: 'Avg Load (kW)' }} }} }} }}\n}});\n\n// ── Section 4 Charts ──\nconst s4RenWeather = {json.dumps(s4_renewable_weather)};\nnew Chart(document.getElementById('chart-renewable-weather'), {{\n  type: 'bar',\n  data: {{\n    labels: s4RenWeather.map(d => d.weather_condition),\n    datasets: [{{\n      label: 'Avg Renewable Ratio',\n      data: s4RenWeather.map(d => +(+d.avg_renewable * 100).toFixed(1)),\n      backgroundColor: ['#10B981', '#3B82F6', '#6366F1', '#F59E0B', '#EF4444'].slice(0, s4RenWeather.length),\n      borderRadius: 6, barPercentage: 0.6,\n    }}]\n  }},\n  options: {{ responsive: true, plugins: {{ legend: {{ display: false }}, tooltip: tooltipStyle }},\n    scales: {{ y: {{ beginAtZero: true, title: {{ display: true, text: 'Renewable %' }}, max: 100 }} }} }}\n}});\n\nconst s4RenTS = {json.dumps(s4_renewable_ts)};\nnew Chart(document.getElementById('chart-renewable-timeslot'), {{\n  type: 'bar',\n  data: {{\n    labels: s4RenTS.map(d => d.time_slot),\n    datasets: [\n      {{ label: 'Renewable %', data: s4RenTS.map(d => +(+d.avg_renewable * 100).toFixed(1)), backgroundColor: '#10B981', borderRadius: 4, yAxisID: 'y' }},\n      {{ label: 'Avg Price', data: s4RenTS.map(d => +(+d.avg_price).toFixed(2)), type: 'line', borderColor: '#F59E0B', backgroundColor: 'rgba(245,158,11,0.1)', fill: true, tension: 0.3, yAxisID: 'y1' }},\n    ]\n  }},\n  options: {{ responsive: true, plugins: {{ tooltip: tooltipStyle }},\n    scales: {{\n      y: {{ beginAtZero: true, position: 'left', title: {{ display: true, text: 'Renewable %' }}, max: 100 }},\n      y1: {{ beginAtZero: true, position: 'right', title: {{ display: true, text: 'Price' }}, grid: {{ drawOnChartArea: false }} }},\n    }} }}\n}});\n\nconst s4RenLoc = {json.dumps(s4_renewable_loc)};\nnew Chart(document.getElementById('chart-renewable-location'), {{\n  type: 'bar',\n  data: {{\n    labels: s4RenLoc.map(d => d.location_type),\n    datasets: [{{\n      label: 'Avg Renewable Ratio',\n      data: s4RenLoc.map(d => +(+d.avg_renewable * 100).toFixed(1)),\n      backgroundColor: s4RenLoc.map(d => C[d.location_type]),\n      borderRadius: 6, barPercentage: 0.6,\n    }}]\n  }},\n  options: {{ responsive: true, plugins: {{ legend: {{ display: false }}, tooltip: tooltipStyle }},\n    scales: {{ y: {{ beginAtZero: true, title: {{ display: true, text: 'Renewable %' }}, max: 100 }} }} }}\n}});\n\nconst s4RenWeatherTS = {json.dumps(s4_renewable_weather_ts)};\nconst weatherTypes = [...new Set(s4RenWeatherTS.map(d => d.weather_condition))];\nnew Chart(document.getElementById('chart-renewable-weather-timeslot'), {{\n  type: 'bar',\n  data: {{\n    labels: tsOrder,\n    datasets: weatherTypes.map((w, i) => ({{\n      label: w,\n      data: tsOrder.map(ts => {{\n        const d = s4RenWeatherTS.find(r => r.weather_condition === w && r.time_slot === ts);\n        return d ? +(+d.avg_renewable * 100).toFixed(1) : 0;\n      }}),\n      backgroundColor: ['#10B981', '#3B82F6', '#6366F1', '#F59E0B', '#EF4444'][i % 5],\n      borderRadius: 3,\n    }}))\n  }},\n  options: {{ responsive: true, plugins: {{ tooltip: tooltipStyle }},\n    scales: {{ y: {{ beginAtZero: true, title: {{ display: true, text: 'Renewable %' }}, max: 100 }} }} }}\n}});\n\n// ── Section 5 Charts ──\nconst s5Profiles = {json.dumps(s5_profiles)};\nnew Chart(document.getElementById('chart-vehicle-count'), {{\n  type: 'doughnut',\n  data: {{\n    labels: s5Profiles.map(d => d.vehicle_type),\n    datasets: [{{ data: s5Profiles.map(d => d.sessions), backgroundColor: ['#3B82F6', '#F59E0B', '#10B981', '#6366F1', '#EF4444', '#EC4899', '#14B8A6'], borderWidth: 0 }}]\n  }},\n  options: {{ responsive: true, plugins: {{ tooltip: tooltipStyle, legend: {{ position: 'right' }} }} }}\n}});\n\nnew Chart(document.getElementById('chart-vehicle-energy'), {{\n  type: 'bar',\n  data: {{\n    labels: s5Profiles.map(d => d.vehicle_type),\n    datasets: [{{\n      label: 'Avg Energy (kWh)',\n      data: s5Profiles.map(d => +d.avg_energy.toFixed(1)),\n      backgroundColor: '#6366F1', borderRadius: 6, barPercentage: 0.6,\n    }}]\n  }},\n  options: {{ responsive: true, plugins: {{ legend: {{ display: false }}, tooltip: tooltipStyle }},\n    scales: {{ y: {{ beginAtZero: true, title: {{ display: true, text: 'kWh' }} }} }} }}\n}});\n\nconst s5Priority = {json.dumps(s5_priority)};\nnew Chart(document.getElementById('chart-priority-stacked'), {{\n  type: 'bar',\n  data: {{\n    labels: s5Priority.map(d => d.vehicle_type),\n    datasets: [\n      {{ label: 'Low', data: s5Priority.map(d => d.Low), backgroundColor: '#10B981', borderRadius: 2 }},\n      {{ label: 'Medium', data: s5Priority.map(d => d.Medium), backgroundColor: '#F59E0B', borderRadius: 2 }},\n      {{ label: 'High', data: s5Priority.map(d => d.High), backgroundColor: '#EF4444', borderRadius: 2 }},\n    ]\n  }},\n  options: {{ responsive: true, plugins: {{ tooltip: tooltipStyle }},\n    scales: {{ x: {{ stacked: true }}, y: {{ stacked: true, title: {{ display: true, text: 'Sessions' }} }} }} }}\n}});\n\n// ── Section 6 Charts ──\nconst s6RewardTS = {json.dumps(s6_reward_ts)};\nnew Chart(document.getElementById('chart-reward-timeslot'), {{\n  type: 'bar',\n  data: {{\n    labels: s6RewardTS.map(d => d.time_slot),\n    datasets: [{{\n      label: 'Avg Optimization Reward',\n      data: s6RewardTS.map(d => +d.avg_reward.toFixed(2)),\n      backgroundColor: tsOrder.map(t => C[t]),\n      borderRadius: 6, barPercentage: 0.6,\n    }}]\n  }},\n  options: {{ responsive: true, plugins: {{ legend: {{ display: false }}, tooltip: tooltipStyle }},\n    scales: {{ y: {{ title: {{ display: true, text: 'Reward Score' }} }} }} }}\n}});\n\nconst s6RewardLoc = {json.dumps(s6_reward_loc)};\nnew Chart(document.getElementById('chart-reward-location'), {{\n  type: 'bar',\n  data: {{\n    labels: s6RewardLoc.map(d => d.location_type),\n    datasets: [{{\n      label: 'Avg Optimization Reward',\n      data: s6RewardLoc.map(d => +d.avg_reward.toFixed(2)),\n      backgroundColor: s6RewardLoc.map(d => C[d.location_type]),\n      borderRadius: 6, barPercentage: 0.6,\n    }}]\n  }},\n  options: {{ responsive: true, plugins: {{ legend: {{ display: false }}, tooltip: tooltipStyle }},\n    scales: {{ y: {{ title: {{ display: true, text: 'Reward Score' }} }} }} }}\n}});\n\n</script>\n</body>\n</html>\n\"\"\"\n\n# ── Write Output ─────────────────────────────────────────────────────────────\nwith open(\"/app/output/final_report.html\", \"w\", encoding=\"utf-8\") as f:\n    f.write(html_content)\n\nprint(f\"Report generated: /app/output/final_report.html ({len(html_content):,} bytes)\")\n", "numLines": 1259, "startLine": 1, "totalLines": 1259}}

