    --radius: 10px;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background: var(--bg); color: var(--text);
    line-height: 1.6; padding: 0;
  }}
  .container {{ max-width: 1280px; margin: 0 auto; padding: 24px; }}
  .report-header {{
    background: linear-gradient(135deg, #1E3A5F 0%, #0F172A 100%);
    border-bottom: 2px solid var(--accent);
    padding: 40px 0 32px; margin-bottom: 32px;
  }}
  .report-header .container {{ display: flex; align-items: center; gap: 24px; flex-wrap: wrap; }}
  .header-icon {{
    width: 64px; height: 64px; border-radius: 16px;
    background: var(--accent); display: flex; align-items: center;
    justify-content: center; font-size: 28px; flex-shrink: 0;
  }}
  .header-text h1 {{ font-size: 26px; font-weight: 700; margin-bottom: 4px; }}
  .header-text p {{ color: var(--text-dim); font-size: 14px; }}
  .nav-bar {{
    background: var(--surface); border-radius: var(--radius);
    padding: 8px; margin-bottom: 32px; display: flex; gap: 4px;
    overflow-x: auto;
  }}
  .nav-bar a {{
