#!/usr/bin/env python3
"""Generate EV Charging Network Performance & Grid Optimization Report."""

import pandas as pd
import numpy as np
import json
import html

# ── Load Data ────────────────────────────────────────────────────────────────
df = pd.read_csv("/app/benchmark/data.csv")
total_sessions = len(df)

# ── Discover actual data dimensions ─────────────────────────────────────────
location_types = sorted(df["location_type"].unique().tolist())
vehicle_types = sorted(df["vehicle_type"].unique().tolist(), key=lambda v: df[df["vehicle_type"]==v].shape[0], reverse=True)
time_slots = ["Off-Peak", "Peak"]  # Only these two exist
weather_conditions = sorted(df["weather_condition"].unique().tolist())
day_order = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
traffic_order = ["Low", "Medium", "High"]

# ── KPI Computation ──────────────────────────────────────────────────────────
avg_waiting_time = df["waiting_time"].mean()
avg_energy_consumed = df["energy_consumed_kWh"].mean()
mean_station_load = df["station_load"].mean()
mean_renewable_ratio = df["renewable_energy_ratio"].mean()
mean_optimization_reward = df["optimization_reward"].mean()

# ── Section 1: Station Utilization & Demand Analysis ─────────────────────────
demand_by_location = df.groupby("location_type").agg(
    sessions=("energy_consumed_kWh", "count"),
    avg_demand=("charging_demand", "mean"),
    avg_energy=("energy_consumed_kWh", "mean"),
    avg_station_load=("station_load", "mean"),
).reset_index()

demand_by_station = df.groupby("station_id").agg(
    location_type=("location_type", "first"),
    sessions=("energy_consumed_kWh", "count"),
    avg_demand=("charging_demand", "mean"),
    avg_energy=("energy_consumed_kWh", "mean"),
    avg_station_load=("station_load", "mean"),
    avg_queue=("queue_length", "mean"),
).reset_index().sort_values("avg_demand", ascending=False)

top10_stations = demand_by_station.head(10)

demand_by_timeslot_location = df.groupby(["time_slot", "location_type"]).agg(
    avg_demand=("charging_demand", "mean"),
    sessions=("energy_consumed_kWh", "count"),
    avg_queue=("queue_length", "mean"),
).reset_index()
demand_by_timeslot_location["time_slot"] = pd.Categorical(
    demand_by_timeslot_location["time_slot"], categories=time_slots, ordered=True
)
demand_by_timeslot_location = demand_by_timeslot_location.sort_values("time_slot")

# ── Section 2: Queue Length & Waiting Time Analysis ──────────────────────────
wait_by_timeslot_location = df.groupby(["time_slot", "location_type"]).agg(
    avg_wait=("waiting_time", "mean"),
    avg_queue=("queue_length", "mean"),
    median_wait=("waiting_time", "median"),
    p90_wait=("waiting_time", lambda x: x.quantile(0.9)),
    sessions=("waiting_time", "count"),
).reset_index()
wait_by_timeslot_location["time_slot"] = pd.Categorical(
    wait_by_timeslot_location["time_slot"], categories=time_slots, ordered=True
)
wait_by_timeslot_location = wait_by_timeslot_location.sort_values(["time_slot", "location_type"])

wait_by_traffic = df.groupby("traffic_density").agg(
    avg_wait=("waiting_time", "mean"),
    avg_queue=("queue_length", "mean"),
    sessions=("waiting_time", "count"),
).reset_index()

wait_by_vehicle = df.groupby("vehicle_type").agg(
    avg_wait=("waiting_time", "mean"),
    avg_queue=("queue_length", "mean"),
    sessions=("waiting_time", "count"),
).reset_index().sort_values("avg_wait", ascending=False)

wait_by_station = df.groupby("station_id").agg(
    location_type=("location_type", "first"),
    avg_wait=("waiting_time", "mean"),
    avg_queue=("queue_length", "mean"),
    sessions=("waiting_time", "count"),
).reset_index().sort_values("avg_wait", ascending=False)

top10_wait_stations = wait_by_station.head(10)

# ── Section 3: Energy Consumption & Grid Load Patterns ───────────────────────
energy_by_timeslot = df.groupby("time_slot").agg(
    avg_energy=("energy_consumed_kWh", "mean"),
    avg_load=("station_load", "mean"),
    avg_power=("charging_power_kW", "mean"),
    sessions=("energy_consumed_kWh", "count"),
).reset_index()
energy_by_timeslot["time_slot"] = pd.Categorical(
    energy_by_timeslot["time_slot"], categories=time_slots, ordered=True
)
energy_by_timeslot = energy_by_timeslot.sort_values("time_slot")

energy_by_day = df.groupby("day_of_week").agg(
    avg_energy=("energy_consumed_kWh", "mean"),
    avg_load=("station_load", "mean"),
    sessions=("energy_consumed_kWh", "count"),
).reset_index()
energy_by_day["day_of_week"] = pd.Categorical(
    energy_by_day["day_of_week"], categories=day_order, ordered=True
)
energy_by_day = energy_by_day.sort_values("day_of_week")

load_by_timeslot_location = df.groupby(["time_slot", "location_type"]).agg(
    avg_load=("station_load", "mean"),
    avg_energy=("energy_consumed_kWh", "mean"),
    sessions=("energy_consumed_kWh", "count"),
).reset_index()
load_by_timeslot_location["time_slot"] = pd.Categorical(
    load_by_timeslot_location["time_slot"], categories=time_slots, ordered=True
)
load_by_timeslot_location = load_by_timeslot_location.sort_values(["time_slot", "location_type"])

power_load = df.groupby("charging_power_kW").agg(
    avg_load=("station_load", "mean"),
    avg_energy=("energy_consumed_kWh", "mean"),
    sessions=("energy_consumed_kWh", "count"),
).reset_index().sort_values("charging_power_kW")

# ── Section 4: Renewable Energy Integration & Dynamic Pricing ────────────────
renewable_by_weather = df.groupby("weather_condition").agg(
    avg_renewable=("renewable_energy_ratio", "mean"),
    avg_price=("electricity_price", "mean"),
    sessions=("energy_consumed_kWh", "count"),
).reset_index().sort_values("avg_renewable", ascending=False)

renewable_by_timeslot = df.groupby("time_slot").agg(
    avg_renewable=("renewable_energy_ratio", "mean"),
    avg_price=("electricity_price", "mean"),
    sessions=("energy_consumed_kWh", "count"),
).reset_index()
renewable_by_timeslot["time_slot"] = pd.Categorical(
    renewable_by_timeslot["time_slot"], categories=time_slots, ordered=True
)
renewable_by_timeslot = renewable_by_timeslot.sort_values("time_slot")

renewable_by_location = df.groupby("location_type").agg(
    avg_renewable=("renewable_energy_ratio", "mean"),
    avg_price=("electricity_price", "mean"),
    sessions=("energy_consumed_kWh", "count"),
).reset_index()

renewable_by_weather_timeslot = df.groupby(["weather_condition", "time_slot"]).agg(
    avg_renewable=("renewable_energy_ratio", "mean"),
    sessions=("energy_consumed_kWh", "count"),
).reset_index()
renewable_by_weather_timeslot["time_slot"] = pd.Categorical(
    renewable_by_weather_timeslot["time_slot"], categories=time_slots, ordered=True
)
renewable_by_weather_timeslot = renewable_by_weather_timeslot.sort_values(["weather_condition", "time_slot"])

price_renewable_corr = df["electricity_price"].corr(df["renewable_energy_ratio"])
price_demand_corr = df["electricity_price"].corr(df["charging_demand"])
renewable_reward_corr = df["renewable_energy_ratio"].corr(df["optimization_reward"])

# ── Section 5: Vehicle Charging Behavior & Session Profiles ──────────────────
vehicle_profiles = df.groupby("vehicle_type").agg(
    sessions=("energy_consumed_kWh", "count"),
    avg_battery=("battery_capacity_kWh", "mean"),
    avg_initial_soc=("initial_soc", "mean"),
    avg_final_soc=("final_soc", "mean"),
    avg_energy=("energy_consumed_kWh", "mean"),
    avg_duration=("charging_duration", "mean"),
    avg_power=("charging_power_kW", "mean"),
    avg_wait=("waiting_time", "mean"),
).reset_index().sort_values("sessions", ascending=False)

priority_dist = df.groupby(["vehicle_type", "charging_priority"]).size().reset_index(name="count")
priority_pivot = priority_dist.pivot_table(
    index="vehicle_type", columns="charging_priority", values="count", fill_value=0
).reset_index()
for col in ["Low", "Medium", "High"]:
    if col not in priority_pivot.columns:
        priority_pivot[col] = 0
priority_pivot = priority_pivot[["vehicle_type", "Low", "Medium", "High"]]

# ── Section 6: Optimization Insights ─────────────────────────────────────────
reward_by_timeslot = df.groupby("time_slot").agg(
    avg_reward=("optimization_reward", "mean"),
    sessions=("optimization_reward", "count"),
).reset_index()
reward_by_timeslot["time_slot"] = pd.Categorical(
    reward_by_timeslot["time_slot"], categories=time_slots, ordered=True
)
reward_by_timeslot = reward_by_timeslot.sort_values("time_slot")

reward_by_location = df.groupby("location_type").agg(
    avg_reward=("optimization_reward", "mean"),
    sessions=("optimization_reward", "count"),
).reset_index()

reward_by_priority = df.groupby("charging_priority").agg(
    avg_reward=("optimization_reward", "mean"),
    avg_renewable=("renewable_energy_ratio", "mean"),
    avg_price=("electricity_price", "mean"),
    sessions=("optimization_reward", "count"),
).reset_index()

peak_df = df[df["time_slot"] == "Peak"]
offpeak_df = df[df["time_slot"] == "Off-Peak"]

peak_avg_load = peak_df["station_load"].mean()
offpeak_avg_load = offpeak_df["station_load"].mean()
peak_avg_renewable = peak_df["renewable_energy_ratio"].mean()
offpeak_avg_renewable = offpeak_df["renewable_energy_ratio"].mean()
peak_avg_wait = peak_df["waiting_time"].mean()
offpeak_avg_wait = offpeak_df["waiting_time"].mean()
peak_avg_reward = peak_df["optimization_reward"].mean()
offpeak_avg_reward = offpeak_df["optimization_reward"].mean()

high_renewable = df[df["renewable_energy_ratio"] > 0.5]
low_renewable = df[df["renewable_energy_ratio"] <= 0.5]
hr_avg_reward = high_renewable["optimization_reward"].mean()
lr_avg_reward = low_renewable["optimization_reward"].mean()

urban_peak_df = df[(df["location_type"] == "Urban") & (df["time_slot"] == "Peak")]
urban_offpeak_df = df[(df["location_type"] == "Urban") & (df["time_slot"] == "Off-Peak")]
urban_peak_wait = urban_peak_df["waiting_time"].mean()
urban_offpeak_wait = urban_offpeak_df["waiting_time"].mean()
highway_peak_df = df[(df["location_type"] == "Highway") & (df["time_slot"] == "Peak")]
highway_offpeak_df = df[(df["location_type"] == "Highway") & (df["time_slot"] == "Off-Peak")]
highway_peak_wait = highway_peak_df["waiting_time"].mean()
highway_offpeak_wait = highway_offpeak_df["waiting_time"].mean()

high_renewable_offpeak = df[(df["renewable_energy_ratio"] > 0.5) & (df["time_slot"] == "Off-Peak")]
high_renewable_peak = df[(df["renewable_energy_ratio"] > 0.5) & (df["time_slot"] == "Peak")]
hr_offpeak_count = len(high_renewable_offpeak)
hr_peak_count = len(high_renewable_peak)

# Top vehicle by energy per session
bus_energy = vehicle_profiles[vehicle_profiles["vehicle_type"] == "Bus"]["avg_energy"].values
car_energy = vehicle_profiles[vehicle_profiles["vehicle_type"] == "Car"]["avg_energy"].values
tw_energy = vehicle_profiles[vehicle_profiles["vehicle_type"] == "Two-Wheeler"]["avg_energy"].values

# ── Helpers ───────────────────────────────────────────────────────────────────
def df_to_json(d):
    return json.loads(d.to_json(orient="records"))

# ── Build HTML ───────────────────────────────────────────────────────────────
html_content = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>EV Charging Network Performance &amp; Grid Optimization Report</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --bg: #0F172A;
    --surface: #1E293B;
    --surface2: #334155;
    --text: #F1F5F9;
    --text-dim: #94A3B8;
    --accent: #3B82F6;
    --accent2: #6366F1;
    --green: #10B981;
    --amber: #F59E0B;
    --red: #EF4444;
    --border: #475569;
    --radius: 10px;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background: var(--bg); color: var(--text);
    line-height: 1.6; padding: 0;
  }}
  .container {{ max-width: 1280px; margin: 0 auto; padding: 24px; }}
  .report-header {{
    background: linear-gradient(135deg, #1E3A5F 0%, #0F172A 100%);
    border-bottom: 2px solid var(--accent);
    padding: 40px 0 32px; margin-bottom: 32px;
  }}
  .report-header .container {{ display: flex; align-items: center; gap: 24px; flex-wrap: wrap; }}
  .header-icon {{
    width: 64px; height: 64px; border-radius: 16px;
    background: var(--accent); display: flex; align-items: center;
    justify-content: center; font-size: 28px; flex-shrink: 0;
  }}
  .header-text h1 {{ font-size: 26px; font-weight: 700; margin-bottom: 4px; }}
  .header-text p {{ color: var(--text-dim); font-size: 14px; }}
  .nav-bar {{
    background: var(--surface); border-radius: var(--radius);
    padding: 8px; margin-bottom: 32px; display: flex; gap: 4px;
    overflow-x: auto;
  }}
  .nav-bar a {{
    color: var(--text-dim); text-decoration: none; padding: 8px 16px;
    border-radius: 6px; font-size: 13px; white-space: nowrap;
    transition: all 0.2s;
  }}
  .nav-bar a:hover {{ background: var(--surface2); color: var(--text); }}
  .kpi-banner {{
    display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px;
    margin-bottom: 40px;
  }}
  .kpi-card {{
    background: var(--surface); border-radius: var(--radius);
    padding: 20px; border: 1px solid var(--border); position: relative;
    overflow: hidden;
  }}
  .kpi-card::before {{
    content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px;
  }}
  .kpi-card:nth-child(1)::before {{ background: var(--amber); }}
  .kpi-card:nth-child(2)::before {{ background: var(--accent); }}
  .kpi-card:nth-child(3)::before {{ background: var(--red); }}
  .kpi-card:nth-child(4)::before {{ background: var(--green); }}
  .kpi-card:nth-child(5)::before {{ background: var(--accent2); }}
  .kpi-label {{ font-size: 12px; color: var(--text-dim); text-transform: uppercase;
    letter-spacing: 0.5px; margin-bottom: 8px; }}
  .kpi-value {{ font-size: 28px; font-weight: 700; }}
  .kpi-unit {{ font-size: 13px; color: var(--text-dim); margin-top: 2px; }}
  .section {{ margin-bottom: 48px; scroll-margin-top: 24px; }}
  .section-header {{
    display: flex; align-items: center; gap: 12px;
    margin-bottom: 20px; padding-bottom: 12px;
    border-bottom: 1px solid var(--border);
  }}
  .section-number {{
    width: 32px; height: 32px; border-radius: 8px;
    background: var(--accent); color: white;
    display: flex; align-items: center; justify-content: center;
    font-size: 14px; font-weight: 700; flex-shrink: 0;
  }}
  .section-header h2 {{ font-size: 20px; font-weight: 600; }}
  .chart-grid {{
    display: grid; grid-template-columns: 1fr 1fr; gap: 20px;
    margin-bottom: 20px;
  }}
  .chart-grid.full {{ grid-template-columns: 1fr; }}
  .chart-card {{
    background: var(--surface); border-radius: var(--radius);
    padding: 20px; border: 1px solid var(--border);
  }}
  .chart-card h3 {{ font-size: 14px; color: var(--text-dim); margin-bottom: 12px;
    font-weight: 500; text-transform: uppercase; letter-spacing: 0.3px; }}
  .chart-card canvas {{ max-height: 320px; }}
  .data-table {{ width: 100%; border-collapse: collapse; font-size: 13px; }}
  .data-table th {{
    text-align: left; padding: 10px 12px; background: var(--surface2);
    color: var(--text-dim); font-weight: 600; font-size: 11px;
    text-transform: uppercase; letter-spacing: 0.5px;
    border-bottom: 1px solid var(--border);
